local EaselMaker = {}
local PRODUCTS = {
    iron_easel = { name = "Železno stojalo za platna", ironCost = 2, woodCost = 3, leatherCost = 1, time = 5, cost = 175, prestige = 3, happiness = 2, description = "Železno stojalo za slikanje na platnu." },
    bronze_easel = { name = "Bronasto stojalo za platna", bronzeCost = 2, ironCost = 1, woodCost = 3, leatherCost = 1, time = 7, cost = 420, prestige = 5, happiness = 3, description = "Bronasto stojalo za atelje." },
    silver_easel = { name = "Srebrno stojalo za platna", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 11, cost = 1020, prestige = 10, happiness = 4, description = "Srebrno stojalo za plemiške slikarje." },
    gilded_easel = { name = "Pozlačeno stojalo za platna", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 15, cost = 2200, prestige = 19, happiness = 5, description = "Pozlačeno stojalo za dvorne slikarje." },
    jewel_set_easel = { name = "Draguljasto stojalo za platna", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 19, cost = 4750, prestige = 35, happiness = 7, description = "Draguljasto stojalo za kraljeve slikarje." },
    royal_sovereign_easel = { name = "Kraljevski suvereno stojalo za platna", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 26, cost = 10200, prestige = 68, happiness = 13, description = "Suvereno stojalo z biseri za krono." },
}
local BUILDINGS = {
    easel_workshop = { name = "Stojalna delavnica", cost = { gold = 335, wood = 195, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    easel_house = { name = "Stojalna hiša", cost = { gold = 1215, wood = 380, stone = 270, silver = 7, iron = 7 }, upkeep = 26, qualityBonus = 18 },
    master_easel_atelier = { name = "Mojstrski stojalni atelje", cost = { gold = 3030, wood = 440, stone = 525, silver = 36, gold = 7 }, upkeep = 72, qualityBonus = 30 },
    sovereign_easel_palace = { name = "Suverena stojalna palača", cost = { gold = 13050, wood = 680, stone = 835, gold = 84, jewel = 19 }, upkeep = 257, qualityBonus = 55, prestigeBonus = 50 },
}
EaselMaker.ironStock = 10; EaselMaker.bronzeStock = 8; EaselMaker.woodStock = 18; EaselMaker.leatherStock = 8; EaselMaker.silverStock = 8; EaselMaker.goldStock = 6; EaselMaker.jewelStock = 4; EaselMaker.pearlStock = 4
EaselMaker.productStock = {}; EaselMaker.buildings = {}; EaselMaker.maker = nil; EaselMaker.activeMaking = {}; EaselMaker.totalProducts = 0; EaselMaker.dayTimer = 0
function EaselMaker.init() EaselMaker.ironStock=10; EaselMaker.bronzeStock=8; EaselMaker.woodStock=18; EaselMaker.leatherStock=8; EaselMaker.silverStock=8; EaselMaker.goldStock=6; EaselMaker.jewelStock=4; EaselMaker.pearlStock=4; EaselMaker.productStock={}; EaselMaker.buildings={}; EaselMaker.maker=nil; EaselMaker.activeMaking={}; EaselMaker.totalProducts=0; EaselMaker.dayTimer=0; print("[EaselMaker] Royal Easel Maker System initialized (6 products, 4 buildings)") end
function EaselMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; EaselMaker.maker={name=n or ("Stojalar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalar najet: %s (spretnost: %d)",EaselMaker.maker.name,s),"success") end; return true end
function EaselMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function EaselMaker.build(id) local ok,e=EaselMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(EaselMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function EaselMaker.getQualityBonus() local b=0; for _,bd in ipairs(EaselMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function EaselMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and EaselMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and EaselMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and EaselMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and EaselMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and EaselMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and EaselMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and EaselMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and EaselMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #EaselMaker.buildings==0 then return false,"Potrebna stojalna delavnica" end; if not EaselMaker.maker then return false,"Potreben stojalar" end; return true end
function EaselMaker.make(pt,qty) qty=qty or 1; local ok,e=EaselMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then EaselMaker.ironStock=EaselMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then EaselMaker.bronzeStock=EaselMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then EaselMaker.woodStock=EaselMaker.woodStock-d.woodCost*qty end; if d.leatherCost then EaselMaker.leatherStock=EaselMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then EaselMaker.silverStock=EaselMaker.silverStock-d.silverCost*qty end; if d.goldCost then EaselMaker.goldStock=EaselMaker.goldStock-d.goldCost*qty end; if d.jewelCost then EaselMaker.jewelStock=EaselMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then EaselMaker.pearlStock=EaselMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if EaselMaker.maker then t=math.max(1,t-math.floor(EaselMaker.maker.skill/13)) end; table.insert(EaselMaker.activeMaking,{id="easel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function EaselMaker.completeMaking(m) local q=1.0+(EaselMaker.getQualityBonus()/100); if EaselMaker.maker then q=q+(EaselMaker.maker.skill/140) end; q=math.min(2.5,q); EaselMaker.productStock[m.productType]=(EaselMaker.productStock[m.productType] or 0)+m.quantity; EaselMaker.totalProducts=EaselMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if EaselMaker.maker then EaselMaker.maker.itemsMade=EaselMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then EaselMaker.maker.skill=math.min(100,EaselMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"easel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function EaselMaker.update(dt) if not _G.state then return end; EaselMaker.dayTimer=EaselMaker.dayTimer+dt; if EaselMaker.dayTimer>=30 then EaselMaker.dayTimer=0; for i=#EaselMaker.activeMaking,1,-1 do local m=EaselMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then EaselMaker.completeMaking(m); table.remove(EaselMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(EaselMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if EaselMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function EaselMaker.getStats() return {ironStock=EaselMaker.ironStock,bronzeStock=EaselMaker.bronzeStock,woodStock=EaselMaker.woodStock,leatherStock=EaselMaker.leatherStock,silverStock=EaselMaker.silverStock,goldStock=EaselMaker.goldStock,jewelStock=EaselMaker.jewelStock,pearlStock=EaselMaker.pearlStock,productStock=EaselMaker.productStock,numBuildings=#EaselMaker.buildings,hasMaker=EaselMaker.maker~=nil,makerName=EaselMaker.maker and EaselMaker.maker.name or "—",makerSkill=EaselMaker.maker and EaselMaker.maker.skill or 0,activeMaking=#EaselMaker.activeMaking,totalProducts=EaselMaker.totalProducts} end
return EaselMaker
